def files_with_both(token_a: str, token_b: str) -> list[str]:
    actual = {str(p.relative_to(ROOT)) for folder, suffix in (("docs", "*.md"), ("scripts", "*.py")) for p in (ROOT / folder).glob(suffix) if not is_excluded_review_stack(str(p.relative_to(ROOT)))}
    expected = {p for p in HISTORICAL_INPUT_PATHS if not is_excluded_review_stack(p)}
    if actual != expected:
        raise RuntimeError("Search corpus differs from declared inputs")
    hits: list[str] = []
    for folder, suffix in (("docs", "*.md"), ("scripts", "*.py")):
        for path in sorted((ROOT / folder).glob(suffix)):
            rel = str(path.relative_to(ROOT))
            if is_excluded_review_stack(rel):
                continue
            text = path.read_text(encoding="utf-8", errors="ignore")
            if token_a in text and token_b in text:
                hits.append(rel)
    return hits


